fn shared_finish_inductive(pre: Self, post: Self, r: int) {
    assert forall |x| 0 <= x.0 < post.rc_width implies
        post.ref_counts.index(x.0) == post.shared_pending.count(x.0) as int
            + Self::filter_r(post.shared_guard, x.0).len() as int by {
        if x.0 == r {
            assert(pre.ref_counts.index(r) == post.ref_counts.index(r));
            assert(post.shared_pending.count(r) == pre.shared_pending.count(r) - 1);
